  ($qb$HEAIL-CFS-MCQ-022$qb$, $qb$A5-05$qb$, $qb$MCQ$qb$, $qb$What is the main risk of escalating a cross-department problem early?$qb$, $qb$You lose the cooperation you will need next time$qb$, $qb$It makes the problem look worse than it is$qb$, $qb$It takes longer than solving it directly$qb$, $qb$Your manager may not support you$qb$, $qb$The other department will escalate too$qb$, 5, 3, 2, 1, 0, true),
  ($qb$HEAIL-CFS-MCQ-023$qb$, $qb$A5-05$qb$, $qb$MCQ$qb$, $qb$A request from another department seems unreasonable. What is best?$qb$, $qb$Ask what it is for before deciding anything$qb$, $qb$Explain why it is unreasonable$qb$, $qb$Do what you can of it$qb$, $qb$Ask them to put it in writing$qb$, $qb$Refuse it and explain why$qb$, 5, 3, 2, 1, 0, true),
  ($qb$HEAIL-CFS-MCQ-024$qb$, $qb$A5-05$qb$, $qb$MCQ$qb$, $qb$What most reliably improves how two departments work together?$qb$, $qb$People from each spending time in the other$qb$, $qb$Regular meetings between the two$qb$, $qb$A clear agreement on how work passes$qb$, $qb$Shared targets between them$qb$, $qb$Better communication between managers$qb$, 5, 3, 2, 1, 0, true),
